{
  "justification": "A comparatively high authoritarian score and the prominence of immigration and terrorism elevate Authority and Loyalty. Economic and health concerns follow, while low explicit salience for inequality and morals plus only mildly pro-redistribution views place Equality and Sanctity lower.",
  "foundations": [
    {"foundation": "authority", "basis": "Derived authority-liberty mean 6.77 (more authoritarian); salience of terrorism (6.7%), crime (1.0%) and defence (1.4%).", "weight": 0.24},
    {"foundation": "loyalty", "basis": "Immigration is the top issue (26.3%); related group-threat items include terrorism (6.7%), defence (1.4%) and Europe (1.6%).", "weight": 0.22},
    {"foundation": "proportionality", "basis": "Economy-general (19.5%) dominates, with debt/deficit (3.8%), unemployment (2.9%) and taxation (0.5%).", "weight": 0.19},
    {"foundation": "care", "basis": "Health is highly salient (11.3%), with welfare (2.0%), poverty (1.6%) and social care (0.1%).", "weight": 0.17},
    {"foundation": "equality", "basis": "Redistribution placement mean 4.48 (slightly pro-redistribution) but low salience for inequality (2.9%) and living costs (2.3%).", "weight": 0.12},
    {"foundation": "sanctity", "basis": "Very low salience of morals (0.3%) and gender/sexuality/family (0.1%); environment (1.4%) as a modest purity/naturalness cue.", "weight": 0.06}
  ]
}
